<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/** In-app notification (VB11). External channels are logged in `notification_deliveries`. */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $user_id
 * @property string $type
 * @property string $category
 * @property string $icon
 * @property string $title
 * @property string|null $body
 * @property string|null $link
 * @property array|null $actions
 * @property array|null $data
 * @property string|null $dedupe_key
 * @property Carbon|null $read_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Notification extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'ntf';

    protected $fillable = ['user_id', 'type', 'category', 'icon', 'title', 'body', 'link', 'actions', 'data', 'dedupe_key', 'read_at'];

    protected function casts(): array
    {
        return [
            'actions' => 'array',
            'data' => 'array',
            'read_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }
}
